function provisionalFollowupMarkup(projection){const action=projection?.provisional_next_action,audiences={provider:'Request from the provider',claimant:'Request from the claimant',authority:'Request from the authority',internal:'Internal review'};if(projection?.readiness_scope!=='provisional_plan'||action?.enabled!==true||!Object.hasOwn(audiences,action.audience)||!Array.isArray(action.requested_contents)||!action.requested_contents.length)return '';return `<section class="cp-provisional" id="cwProvisionalNextAction" data-audience="${h(action.audience)}"><h3>${h(audiences[action.audience])}</h3><ul>${action.requested_contents.map(text=>`<li>${h(text)}</li>`).join('')}</ul><p class="cp-helper">This fallible proposal has not been sent and does not certify that the customer goal is fulfilled.</p></section>`;}
